  1	// Timeline: every cut lands on a bar of the score; animation steps at 12fps (stop-motion "on twos")
  2	export const DUR = 54;
  3	export const ANIM_FPS = 12;
  4	export const q = t => Math.floor(t * ANIM_FPS + 1e-6) / ANIM_FPS;
  5	export const qc = t => Math.ceil(t * ANIM_FPS - 1e-6) / ANIM_FPS;   // the frame on which the event first appears on screen
  6	
  7	// Monkeys Spinning Monkeys: 143.55 BPM; the track's first beat at 0.07s aligns to film 4.0s (first brick clicks down)
  8	export const BEAT = 60 / 143.555;
  9	export const beat = n => 4.0 + n * BEAT;
 10	export const bar = n => beat(n * 4);
 11	
 12	export const T = {
 13	  firstClick: 4.0,
 14	  title: [4.15, 5.6],
 15	  layer: i => i === 0 ? 4.0 : beat(2 * i),        // rocket No. 1 layer i settles (0..11)
 16	  cone1: bar(6),                                  // 14.03 small cone top
 17	  wobble: bar(7),                                 // 15.70 starts wobbling
 18	  fall: bar(8),                                   // 17.37 falls, music cuts
 19	  sit: 20.9,
 20	  pickUp: 25.2,
 21	  reprise: 26.4,                                  // theme returns softly
 22	  toss: [27.4, 28.2],                             // tosses wheel, tosses flower
 23	  found: 29.0,                                    // finds the big nose cone
 24	  rebuild: 29.9,                                  // parts fly back (one every 0.19s)
 25	  rebuildStep: .19,
 26	  coneLand: 32.5,
 27	  quindar: 32.8,
 28	  count: [33.3, 34.3, 35.3],
 29	  flicker: 35.0,
 30	  ignite: 36.5,                                   // Heroic Age burst
 31	  lift: 37.0,
 32	  land: 44.2,
 33	  walkOut: 45.0,
 34	  placeBrick: 46.6,
 35	  reveal: 48.0,
 36	  end: 51.71,                                    // Heroic Age final accent (after the 10-bar jump cut)
 37	};
 38	
 39	export const VO = [
 40	  { id: 'v1', t: 0.8, text: 'Every rocket starts with one brick.' },
 41	  { id: 'v2', t: 6.0, text: 'Then another. And another.' },
 42	  { id: 'v3', t: 22.6, text: 'The first one fell apart.' },
 43	  { id: 'v4', t: 25.6, text: "That's okay. Now we have spare parts." },
 44	  { id: 'c3', t: T.count[0], text: 'Three…', radio: true },
 45	  { id: 'c2', t: T.count[1], text: 'Two…', radio: true },
 46	  { id: 'c1', t: T.count[2], text: 'One…', radio: true },
 47	  { id: 'v5', t: 45.2, text: 'And every moon base… starts with one brick.' },
 48	];
 49	
 50	// shots: [start, end, name]
 51	export const SHOTS = [
 52	  [0, 3.4, 'macro'], [3.4, bar(1), 'place'],
 53	  [bar(1), bar(2), 'mA'], [bar(2), bar(3), 'mB'], [bar(3), bar(4), 'mC'], [bar(4), bar(5), 'mD'], [bar(5), bar(6), 'mE'],
 54	  [bar(6), 16.9, 'proud'], [16.9, 20.5, 'collapse'], [20.5, 25.0, 'alone'], [25.0, 26.3, 'pickup'], [26.3, 29.8, 'rummage'], [29.8, 32.5, 'rebuild'],
 55	  [32.5, 34.2, 'visor'], [34.2, 35.4, 'fins'], [35.4, T.ignite, 'pad'], [T.ignite, 40.0, 'liftoff'], [40.0, 42.5, 'cruise'],
 56	  [42.5, T.reveal, 'moon'], [T.reveal, T.end, 'reveal'], [T.end, DUR, 'endcard'],
 57	];
 58	export const shotAt = t => SHOTS.find(s => t >= s[0] && t < s[1]) || SHOTS[SHOTS.length - 1];
 59	
 60	export const CREDITS = [
 61	  'Music: “Monkeys Spinning Monkeys”, “Heroic Age” — Kevin MacLeod (incompetech.com), CC BY 4.0',
 62	  'HDRI, wood & props: Poly Haven, CC0 · Voice: Kokoro TTS',
 63	];
 64	// Brick astronaut: a poseable figure built purely from bricks (legs/arms rotate about hips/shoulders, head turns)
 65	import * as THREE from 'three';
 66	import { COL, BRICK, PLATE, brick, plate, mesh, roundGeo, plastic } from './bricks.js';
 67	
 68	export const HIP = PLATE + 2 * BRICK;                 // 2.8
 69	export const SHOULDER = HIP + PLATE + 2 * BRICK;      // 5.6
 70	export const ARM_L = 3 * BRICK;                       // 3.6
 71	
 72	export function makeAstro() {
 73	  const root = new THREE.Group(), body = new THREE.Group(); root.add(body);
 74	  const legs = [-.5, .5].map(x => {
 75	    const g = new THREE.Group(); g.position.set(x, HIP, 0); body.add(g);
 76	    for (let i = 0; i < 2; i++) { const b = brick(1, 1, COL.white); b.position.y = -HIP + PLATE + i * BRICK; g.add(b); }
 77	    const f = plate(1, 2, COL.dgray); f.position.set(0, -HIP, .3); g.add(f);
 78	    return g;
 79	  });
 80	  const hip = plate(2, 2, COL.lgray); hip.position.y = HIP; body.add(hip);
 81	  for (let i = 0; i < 2; i++) { const b = brick(2, 2, COL.white); b.position.y = HIP + PLATE + i * BRICK; body.add(b); }
 82	  for (const [c, dx] of [[COL.red, -.45], [COL.yellow, 0], [COL.blue, .45]]) {
 83	    const b = new THREE.Mesh(new THREE.CylinderGeometry(.16, .16, .1, 20), plastic(c)); b.rotation.x = Math.PI / 2; b.position.set(dx, HIP + PLATE + BRICK * 1.45, 1.03); body.add(b);
 84	  }
 85	  const pack = brick(2, 1, COL.lgray); pack.position.set(0, HIP + PLATE + .2, -1.5); body.add(pack);   // backpack
 86	  const arms = [-1.5, 1.5].map(x => {
 87	    const g = new THREE.Group(); g.position.set(x, SHOULDER - .1, 0); body.add(g);
 88	    for (let i = 0; i < 3; i++) { const b = mesh(roundGeo(.5), COL.white); b.position.y = -ARM_L + i * BRICK; g.add(b); }
 89	    const hand = new THREE.Group(); hand.position.y = -ARM_L - .2; g.add(hand);
 90	    return { g, hand };
 91	  });
 92	  const collar = plate(2, 2, COL.lgray); collar.position.y = SHOULDER; body.add(collar);
 93	  const head = new THREE.Group(); head.position.set(0, SHOULDER + PLATE, 0); body.add(head);
 94	  const helm = mesh(roundGeo(1, BRICK * 2), COL.white); helm.scale.set(1.12, 1, 1.12); head.add(helm);
 95	  const visor = new THREE.Mesh(new THREE.CylinderGeometry(1.17, 1.17, 1.45, 40, 1, true, -1.0, 2.0),
 96	    new THREE.MeshPhysicalMaterial({ color: '#0f2036', roughness: .04, metalness: .3, clearcoat: 1, envMapIntensity: 1.8, side: THREE.DoubleSide }));
 97	  visor.position.y = BRICK; head.add(visor);
 98	  const eyeMat = new THREE.MeshStandardMaterial({ color: '#fff', emissive: '#d8f0ff', emissiveIntensity: .8 });
 99	  const eyes = [-.3, .3].map(ex => { const e = new THREE.Mesh(new THREE.SphereGeometry(.16, 16, 12), eyeMat); e.position.set(ex * 1.3, BRICK * 1.05, 1.2); head.add(e); return e; });
100	  const ant = new THREE.Mesh(new THREE.CylinderGeometry(.05, .05, 1.4, 8), plastic(COL.lgray)); ant.rotation.z = -.5; ant.position.set(1.35, BRICK * 1.9, -.2); head.add(ant);
101	  const tip = new THREE.Mesh(new THREE.SphereGeometry(.18, 16, 12), new THREE.MeshStandardMaterial({ color: '#ff3b30', emissive: '#ff2a1a', emissiveIntensity: 2 })); tip.position.set(1.7, BRICK * 1.9 + .62, -.2); head.add(tip);
102	  root.traverse(o => { if (o.isMesh) o.castShadow = o.receiveShadow = true; });
103	
104	  // pose: all angles in radians; arm = [forward/back x, side raise z]; legs = [left, right] forward/back swing; sit 0..1
105	  function pose(p) {
106	    root.position.set(p.x, p.y ?? 0, p.z); root.rotation.y = p.ry ?? 0;
107	    const sit = p.sit ?? 0;
108	    body.position.y = (p.bob ?? 0) - sit * (HIP - .55);
109	    body.rotation.x = p.lean ?? 0;
110	    legs[0].rotation.x = (p.legs?.[0] ?? 0) - sit * 1.45; legs[1].rotation.x = (p.legs?.[1] ?? 0) - sit * 1.45;
111	    const aL = p.armL ?? [0, 0], aR = p.armR ?? [0, 0];
112	    arms[0].g.rotation.set(aL[0], 0, -aL[1]); arms[1].g.rotation.set(aR[0], 0, aR[1]);
113	    head.rotation.set(p.nod ?? 0, p.look ?? 0, p.tilt ?? 0);
114	    const blink = p.blink ? .15 : 1; eyes.forEach(e => e.scale.set(1, blink, 1));
115	    tip.material.emissiveIntensity = p.tipGlow ?? 2;
116	  }
117	  return { root, body, arms, head, legs, pose };
118	}
119	
120	// walking: φ is the stride phase
121	export function walkPose(phi, amp = .55) {
122	  const s = Math.sin(phi);
123	  return { legs: [s * amp, -s * amp], armL: [-s * amp * .6, .06], armR: [s * amp * .6, .06], bob: Math.abs(Math.cos(phi)) * .18 };
124	}
  1	// Set: real desk (HDRI + walnut + tea set + desk lamp + pencil + a stack of books) + green baseplate + brick moon on top of the books
  2	import * as THREE from 'three';
  3	import { RGBELoader } from 'three/addons/loaders/RGBELoader.js';
  4	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
  5	import { RectAreaLightUniformsLib } from 'three/addons/lights/RectAreaLightUniformsLib.js';
  6	import { COL, PLATE, BRICK, mesh, plate, brickGeo, roundGeo, plastic } from './bricks.js';
  7	import { mulberry } from '/core/lib.js';
  8	
  9	const PH = '/core/assets/polyhaven/';
 10	export const M = 125;              // 1 metre = 125 stud units (8mm)
 11	export const TOP = .3;             // baseplate top surface
 12	export const PAD = { x: 9, z: -2 };
 13	export const PAD_TOP = TOP + PLATE;
 14	export const MOON = { x: -58, z: -34 };
 15	
 16	export async function buildSet(scene) {
 17	  const hdr = await new RGBELoader().loadAsync(PH + 'photo_studio_loft_hall_2k.hdr');
 18	  hdr.mapping = THREE.EquirectangularReflectionMapping;
 19	  scene.environment = hdr; scene.background = hdr;
 20	  scene.backgroundBlurriness = .5; scene.backgroundIntensity = .22; scene.environmentIntensity = .45;
 21	  scene.environmentRotation.y = scene.backgroundRotation.y = 1.2;
 22	
 23	  const tl = new THREE.TextureLoader(), tex = (f, srgb) => { const t = tl.load(PH + f); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(3.5, 3.5); t.anisotropy = 8; if (srgb) t.colorSpace = THREE.SRGBColorSpace; return t; };
 24	  const desk = new THREE.Mesh(new THREE.PlaneGeometry(600, 600), new THREE.MeshStandardMaterial({ map: tex('walnut_diff.jpg', true), normalMap: tex('walnut_nor.jpg'), roughnessMap: tex('walnut_rough.jpg'), roughness: 1 }));
 25	  desk.rotation.x = -Math.PI / 2; desk.position.set(-20, 0, -20); desk.receiveShadow = true; scene.add(desk);
 26	
 27	  // lights
 28	  const key = new THREE.DirectionalLight('#fff4e8', 3.0); key.position.set(-60, 110, 50); key.target.position.set(-10, 0, -10);
 29	  key.castShadow = true; key.shadow.mapSize.set(4096, 4096); key.shadow.bias = -.0004; key.shadow.normalBias = .03; key.shadow.radius = 4;
 30	  Object.assign(key.shadow.camera, { left: -95, right: 95, top: 95, bottom: -95, near: 10, far: 400 }); scene.add(key, key.target);
 31	  const fill = new THREE.DirectionalLight('#cfe0ff', .45); fill.position.set(60, 40, -50); scene.add(fill);
 32	  // softbox: large area light gives the plastic crisp rectangular highlights (the signature of toy photography)
 33	  RectAreaLightUniformsLib.init();
 34	  const box = (col, I, w, h, p, at) => { const l = new THREE.RectAreaLight(col, I, w, h); l.position.set(...p); l.lookAt(...at); scene.add(l); return l; };
 35	  const softKey = box('#fff6ee', 6, 70, 45, [-55, 60, 55], [0, 4, 0]);
 36	  const softRim = box('#e4eeff', 9, 60, 30, [45, 45, -75], [0, 6, 0]);
 37	  const softMoon = box('#fff6ee', 5, 50, 35, [-20, 70, 10], [-58, 17, -34]);
 38	
 39	  // real props
 40	  const gl = new GLTFLoader();
 41	  const load = async n => (await gl.loadAsync(`${PH}${n}/${n}.gltf`)).scene;
 42	  const tea = await load('tea_set_01');
 43	  const keep = { tea_set_01_teapot_01: [30, -44, .6], tea_set_01_teapot_01_lid: [30, -44, .6], tea_set_01_cup_small_01: [44, -18, 2.4], tea_set_01_saucer_circular_04: [44, -18, 0] };
 44	  const dead = [];
 45	  tea.traverse(o => { if (!o.name.startsWith('tea_set_01_')) return; const k = keep[o.name]; if (!k) dead.push(o); else { o.position.set(k[0] / M, o.position.y + (o.name.includes('cup_small') ? .012 : 0), k[1] / M); o.rotation.y = k[2]; } });
 46	  dead.forEach(o => o.parent.remove(o));
 47	  tea.scale.setScalar(M); scene.add(tea);
 48	  const lamp = await load('desk_lamp_arm_01'); lamp.scale.setScalar(M); lamp.position.set(-125, 0, -20); lamp.rotation.y = 1.77; scene.add(lamp);
 49	  for (const o of [tea, lamp]) o.traverse(m => { if (m.isMesh) { m.castShadow = m.receiveShadow = true; } });
 50	  const bulb = new THREE.PointLight('#ffe2b8', 700, 120, 2); bulb.position.set(-75, 46, -32); scene.add(bulb);
 51	
 52	  // pencil
 53	  const pencil = new THREE.Group();
 54	  const body = new THREE.Mesh(new THREE.CylinderGeometry(.95, .95, 22, 6), new THREE.MeshStandardMaterial({ color: '#f3b61f', roughness: .45 }));
 55	  const wood = new THREE.Mesh(new THREE.ConeGeometry(.95, 2.6, 6), new THREE.MeshStandardMaterial({ color: '#e9c89a', roughness: .8 })); wood.position.y = 12.3;
 56	  const lead = new THREE.Mesh(new THREE.ConeGeometry(.3, .8, 12), new THREE.MeshStandardMaterial({ color: '#2b2b2b', roughness: .4 })); lead.position.y = 14;
 57	  const fer = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1.4, 16), new THREE.MeshStandardMaterial({ color: '#b9bcc0', metalness: 1, roughness: .3 })); fer.position.y = -11.7;
 58	  const eras = new THREE.Mesh(new THREE.CylinderGeometry(.95, .95, 1.6, 16), new THREE.MeshStandardMaterial({ color: '#e88a8a', roughness: .8 })); eras.position.y = -13.2;
 59	  pencil.add(body, wood, lead, fer, eras); pencil.rotation.set(Math.PI / 2, 0, 1.1); pencil.position.set(22, .95, 22);
 60	  pencil.traverse(m => { if (m.isMesh) m.castShadow = m.receiveShadow = true; }); scene.add(pencil);
 61	
 62	  // stack of books (moon sits on top)
 63	  const books = new THREE.Group(); books.position.set(MOON.x, 0, MOON.z); scene.add(books);
 64	  const cloth = ['#7b2d26', '#274b6d', '#3d5c3a', '#c9a45c'];
 65	  let by = 0; const R = mulberry(11);
 66	  [[34, 4.2, 25], [31, 3.4, 23], [33, 5, 24], [28, 3.6, 21]].forEach(([w, h, d], i) => {
 67	    const b = new THREE.Group(); b.position.y = by; b.rotation.y = (R() - .5) * .25;
 68	    const cover = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), new THREE.MeshStandardMaterial({ color: cloth[i], roughness: .75 }));
 69	    cover.position.y = h / 2; b.add(cover);
 70	    const pages = new THREE.Mesh(new THREE.BoxGeometry(w - .6, h - .7, d - .3), new THREE.MeshStandardMaterial({ color: '#efe6d2', roughness: .9 }));
 71	    pages.position.set(.4, h / 2, 0); b.add(pages);
 72	    b.traverse(m => { if (m.isMesh) m.castShadow = m.receiveShadow = true; });
 73	    books.add(b); by += h;
 74	  });
 75	  const moonTop = by;
 76	
 77	  // brick moon: highlands stacked from grey round plates + craters
 78	  const moon = new THREE.Group(); moon.position.set(MOON.x, moonTop, MOON.z); scene.add(moon);
 79	  const g1 = new THREE.Mesh(new THREE.CylinderGeometry(10.5, 10.8, PLATE * 2, 48), plastic(COL.lgray)); g1.position.y = PLATE; moon.add(g1);
 80	  for (let i = 0; i < 26; i++) {
 81	    const a = i / 26 * Math.PI * 2 + R() * .2, r = 9 + R() * 1.5, h = PLATE * (2 + Math.floor(R() * 3));
 82	    const m = mesh(roundGeo(R() < .5 ? .5 : 1, h), R() < .3 ? COL.dgray : COL.lgray); m.position.set(Math.cos(a) * r, 0, Math.sin(a) * r); moon.add(m);
 83	  }
 84	  for (const [x, z, r] of [[4, 3, 1.6], [-5, -2, 1.1], [2, -6, .9], [-3, 6, .8]]) {
 85	    const c = new THREE.Mesh(new THREE.CylinderGeometry(r, r * .9, .25, 32), plastic(COL.dgray)); c.position.set(x, PLATE * 2 + .1, z); moon.add(c);
 86	    const rim = new THREE.Mesh(new THREE.TorusGeometry(r, .22, 8, 32), plastic(COL.lgray)); rim.rotation.x = Math.PI / 2; rim.position.set(x, PLATE * 2 + .2, z); moon.add(rim);
 87	  }
 88	  moon.traverse(m => { if (m.isMesh) m.castShadow = m.receiveShadow = true; });
 89	  const MOON_TOP = moonTop + PLATE * 2;
 90	
 91	  // green baseplate + launch pad + hazard stripes
 92	  const bp = new THREE.Mesh(brickGeo(32, 24, .3), new THREE.MeshPhysicalMaterial({ color: '#4f9e3a', roughness: .55, clearcoat: .12, clearcoatRoughness: .5 }));
 93	  bp.receiveShadow = bp.castShadow = true; scene.add(bp);
 94	  const pad = plate(8, 8, COL.dgray); pad.position.set(PAD.x, TOP, PAD.z); scene.add(pad);
 95	  for (let i = 0; i < 8; i++) { const s = plate(1, 1, i % 2 ? COL.black : COL.yellow, { tile: true }); s.position.set(PAD.x - 3.5 + i, PAD_TOP, PAD.z + 4.5); scene.add(s); }
 96	
 97	  return { key, bulb, moon, MOON_TOP, lamp };
 98	}
 99	
100	// ground height: baseplate top within the baseplate, otherwise the desk
101	export const groundY = (x, z) => (Math.abs(x - PAD.x) < 4 && Math.abs(z - PAD.z) < 4) ? PAD_TOP : (Math.abs(x) < 16 && Math.abs(z) < 12) ? TOP : 0;

  1	// Rocket from Spare Parts — Brick Toy style demo
  2	import * as THREE from 'three';
  3	import { makePost } from '/core/three/post.js';
  4	import { clamp, seg, eio, eo, ss, lerp, hash } from '/core/lib.js';
  5	import { COL, BRICK, PLATE, brick } from './bricks.js';
  6	import { DUR, T, VO, shotAt, q, qc, BEAT, CREDITS } from './story.js';
  7	import { buildSet, PAD, PAD_TOP, TOP, MOON } from './set.js';
  8	import { makeAstro, walkPose } from './actors.js';
  9	import { makeRockets } from './rockets.js';
 10	
 11	const W = 1920, H = 1080;
 12	const renderer = new THREE.WebGLRenderer({ antialias: false, preserveDrawingBuffer: true });
 13	renderer.setPixelRatio(2); renderer.setSize(W, H);
 14	renderer.toneMapping = THREE.NeutralToneMapping; renderer.toneMappingExposure = 1.0;
 15	renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
