256	  add('quindar', T.quindar); add('rumble', T.flicker, { d: 1.5, v: .3 }); add('ignite', T.ignite); add('roar', T.ignite, { d: 42.5 - T.ignite });
257	  add('roar', 42.5, { d: T.land - 42.5, v: .35 }); add('thump', qc(T.land), { v: 1 }); add('click', qc(T.placeBrick), { v: 1.1 }); add('click', T.end, { v: 1.2 });
258	  let last = null;   // footsteps: sampled from the performance
259	  for (let f = 0; f < DUR * 12; f++) {
260	    const t = f / 12, A = astroAt(t); if (!A.vis) { last = null; continue; }
261	    const l = A.P.legs?.[0] ?? 0, s = Math.sign(l);
